var MAP=[['M',1000],['CM',900],['D',500],['CD',400],['C',100],['XC',90],['L',50],['XL',40],['X',10],['IX',9],['V',5],['IV',4],['I',1]];
function toRoman(n){
  if(!Number.isInteger(n)||n<1||n>3999) return '';
  var s='';
  for(var i=0;i<MAP.length;i++){ while(n>=MAP[i][1]){ s+=MAP[i][0]; n-=MAP[i][1]; } }
  return s;
}
function fromRoman(s){
  s=(s||'').toUpperCase().trim(); if(!s) return 0;
  var total=0, prev=0;
  for(var i=s.length-1;i>=0;i--){
    var v={I:1,V:5,X:10,L:50,C:100,D:500,M:1000}[s[i]];
    if(v===undefined) return -1;
    if(v<prev) total-=v; else total+=v;
    prev=v;
  }
  return total;
}
function valid(s){ return fromRoman(s)>0; }
var EXPORTS={toRoman:toRoman, fromRoman:fromRoman, valid:valid};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.RomanNumeralForgePure = EXPORTS; }
